"""One-time GEN challenges generated by Brain, with in-process replay protection.

This registry is process-local. Production deployments must replace it with a
durable, atomic shared store before running multiple workers or restarting.
It creates challenges only; it does not contact or attest physical hardware.
"""
from __future__ import annotations

import secrets
import threading
import time
from dataclasses import dataclass
from typing import Any


@dataclass(frozen=True)
class GENChallenge:
    nonce: str
    issuer_id: str
    subject_id: str
    subject_type: str
    operation: str
    issued_at: float
    expires_at: float


class GENChallengeRegistry:
    """Issue scoped nonces and atomically consume each challenge at most once."""

    def __init__(self, *, ttl_seconds: int = 120, clock=time.time) -> None:
        if isinstance(ttl_seconds, bool) or not isinstance(ttl_seconds, int) or not 1 <= ttl_seconds <= 300:
            raise ValueError("GEN_CHALLENGE_TTL_INVALID")
        self._ttl = ttl_seconds
        self._clock = clock
        self._lock = threading.Lock()
        self._pending: dict[str, GENChallenge] = {}

    def issue(self, *, issuer_id: str, subject_id: str, subject_type: str, operation: str) -> GENChallenge:
        for name, value in (("issuer_id", issuer_id), ("subject_id", subject_id),
                            ("subject_type", subject_type), ("operation", operation)):
            if not isinstance(value, str) or not value.strip():
                raise ValueError("GEN_CHALLENGE_FIELD_REQUIRED:" + name)
        if subject_type not in {"ASIC_DEVICE", "HOSTED_ASIC"}:
            raise ValueError("GEN_CHALLENGE_SUBJECT_TYPE_INVALID")
        now = float(self._clock())
        challenge = GENChallenge(
            nonce=secrets.token_urlsafe(32),
            issuer_id=issuer_id,
            subject_id=subject_id,
            subject_type=subject_type,
            operation=operation,
            issued_at=now,
            expires_at=now + self._ttl,
        )
        with self._lock:
            self._purge(now)
            self._pending[challenge.nonce] = challenge
        return challenge

    def consume(self, *, nonce: str, issuer_id: str, subject_id: str,
                subject_type: str, operation: str) -> GENChallenge:
        now = float(self._clock())
        with self._lock:
            challenge = self._pending.pop(nonce, None)
        if challenge is None:
            raise ValueError("GEN_CHALLENGE_UNKNOWN_OR_REPLAYED")
        if challenge.expires_at <= now:
            raise ValueError("GEN_CHALLENGE_EXPIRED")
        expected = (challenge.issuer_id, challenge.subject_id, challenge.subject_type, challenge.operation)
        actual = (issuer_id, subject_id, subject_type, operation)
        if actual != expected:
            raise ValueError("GEN_CHALLENGE_SCOPE_MISMATCH")
        return challenge

    def _purge(self, now: float) -> None:
        expired = [nonce for nonce, challenge in self._pending.items()
                   if challenge.expires_at <= now]
        for nonce in expired:
            self._pending.pop(nonce, None)


__all__ = ["GENChallenge", "GENChallengeRegistry"]
